using System.Text.Json;
using EgorVpn.Routing;

var failures = 0;
var checks = 0;
void Check(string name, Action test) { checks++; try { test(); Console.WriteLine("PASS " + name); } catch(Exception ex) { failures++; Console.WriteLine("FAIL " + name + ": " + ex.Message); } }
void Equal<T>(T expected,T actual) { if(!Equals(expected,actual)) throw new Exception($"Expected {expected}, got {actual}"); }
void True(bool value) { if(!value) throw new Exception("Expected true"); }
void Reject(string input) { True(!DomainNames.TryNormalize(input,out _,out var error)); True(!string.IsNullOrEmpty(error)); }
var catalog = RoutingCatalog.LoadEmbedded();
Check("verbatim seed has 50 direct services and 165 rules",()=> { Equal(50,catalog.Services.Count); Equal(165,catalog.Services.SelectMany(s=>s.Rules).Distinct().Count()); True(catalog.IsValid); Equal("2026.10.08-seed.1",catalog.Version); });
Check("VPN-only has 2 services and 18 proxy rules",()=>{ Equal(2,catalog.VpnOnlyServices.Count); Equal(18,catalog.VpnOnlyServices.SelectMany(s=>s.Rules).Distinct().Count()); True(catalog.VpnOnlyServices.SelectMany(s=>s.Rules).All(r=>r.Route==DomainRoute.Proxy)); });
Check("embedded catalog singleton",()=>True(ReferenceEquals(catalog,RoutingCatalog.LoadEmbedded())));
foreach(var query in new[]{"ГОСУСЛУГИ","гос   услуги","ГОС-УСЛУГИ","ЕСИА","gosuslugi","ESIA","esia.gosuslugi.ru"}) Check("search "+query,()=>True(catalog.Search(query).Any(s=>s.Id=="gosuslugi")));
Check("search unknown never invents services",()=>Equal(0,catalog.Search("unknown_service_name_392").Count));
Check("normalizes URL hostname only",()=>Equal("example.com",DomainNames.Normalize("https://EXAMPLE.COM.:8443/path?q=1#x")));
Check("normalizes IDNA",()=>Equal("xn--e1afmkfd.xn--p1ai",DomainNames.Normalize("Пример.РФ.")));
foreach(var host in new[]{"ru","su","рф","gov.ru","co.uk","github.io","a.ck","foo.kawasaki.jp","localhost","127.0.0.1","[::1]","https://127.1/","user@example.com","https://name:secret@example.com/","https://example.com\\@evil.com","bad..com","-bad.com","bad-.com","a_b.com","a\u0000.com","a.com\r\n","*.example.com","example.com:443","example.com/path",new string('x',64)+".com"}) Check("reject "+host.Replace("\n","\\n"),()=>Reject(host));
Check("PSL exception registrable",()=>Equal("www.ck",DomainNames.Normalize("www.ck")));
Check("PSL exception city.kawasaki.jp",()=>Equal("city.kawasaki.jp",DomainNames.Normalize("city.kawasaki.jp")));
Check("suffix respects domain boundary",()=> {var r=new DomainRule(DomainMatch.Suffix,"gosuslugi.ru",DomainRoute.Direct); True(r.Matches("gosuslugi.ru")); True(r.Matches("esia.gosuslugi.ru")); True(!r.Matches("evilgosuslugi.ru")); True(!r.Matches("gosuslugi.ru.evil.com")); });
Check("exact excludes children",()=>{ var r=new DomainRule(DomainMatch.Exact,"example.com",DomainRoute.Direct); True(r.Matches("example.com")); True(!r.Matches("www.example.com")); });
Check("overlap detects contained exact and suffix",()=>{ var r=new DomainRule(DomainMatch.Suffix,"example.com",DomainRoute.Direct); True(r.Overlaps(new(DomainMatch.Exact,"www.example.com",DomainRoute.Proxy))); True(r.ConflictsWith(new(DomainMatch.Suffix,"deep.example.com",DomainRoute.Proxy))); True(!r.ConflictsWith(new(DomainMatch.Exact,"evil-example.com",DomainRoute.Proxy))); True(!r.ConflictsWith(new(DomainMatch.Suffix,"example.com",DomainRoute.Direct))); });
Check("Full VPN has no direct rules including manual",()=>{var p=new RuRoutingPreferences {CustomRules=new(){new(DomainMatch.Suffix,"example.com",DomainRoute.Direct)}}; var s=RoutingPolicySnapshot.Create(RoutingMode.FullVpn,p); Equal(0,s.DirectRules.Count); Equal(DomainRoute.Proxy,s.MatchHost("esia.gosuslugi.ru")); Equal(DomainRoute.Proxy,s.MatchHost("example.com")); });
Check("RU mode defaults direct only known catalog",()=>{var s=RoutingPolicySnapshot.Create(RoutingMode.RuMode,new()); Equal(RoutingMode.RuMode,s.Mode); Equal(DomainRoute.Direct,s.MatchHost("esia.gosuslugi.ru")); Equal(DomainRoute.Proxy,s.MatchHost("unknown.ru")); Equal(DomainRoute.Proxy,s.MatchHost("youtube.com")); Equal(DomainRoute.Proxy,s.MatchHost("discord.com")); Equal(DomainRoute.Proxy,s.MatchHost("127.0.0.1")); Equal(DomainRoute.Proxy,s.MatchHost("")); });
Check("disabled service removes its contribution",()=>{var s=RoutingPolicySnapshot.Create(RoutingMode.RuMode,new(){DisabledServiceIds=new(){"gosuslugi"}}); Equal(DomainRoute.Proxy,s.MatchHost("esia.gosuslugi.ru")); });
Check("manual contribution survives service disabled",()=>{var s=RoutingPolicySnapshot.Create(RoutingMode.RuMode,new(){DisabledServiceIds=new(){"gosuslugi"},CustomRules=new(){new(DomainMatch.Suffix,"gosuslugi.ru",DomainRoute.Direct)}}); Equal(DomainRoute.Direct,s.MatchHost("esia.gosuslugi.ru")); });
Check("manual proxy wins direct catalog and overlap",()=>{var s=RoutingPolicySnapshot.Create(RoutingMode.RuMode,new(){CustomRules=new(){new(DomainMatch.Exact,"esia.gosuslugi.ru",DomainRoute.Proxy)}}); Equal(DomainRoute.Proxy,s.MatchHost("esia.gosuslugi.ru")); Equal(DomainRoute.Direct,s.MatchHost("www.gosuslugi.ru")); });
Check("VPN protection survives manual direct suffix",()=>{var s=RoutingPolicySnapshot.Create(RoutingMode.RuMode,new(){CustomRules=new(){new(DomainMatch.Suffix,"youtube.com",DomainRoute.Direct)}}); Equal(DomainRoute.Proxy,s.MatchHost("www.youtube.com")); True(s.FindConflicts(new(DomainMatch.Suffix,"youtube.com",DomainRoute.Direct)).Count>0); });
Check("snapshot captures immutable copies",()=>{var p=new RuRoutingPreferences(); var s=RoutingPolicySnapshot.Create(RoutingMode.RuMode,p); p.DisabledServiceIds.Add("gosuslugi"); p.CustomRules.Add(new(DomainMatch.Suffix,"gosuslugi.ru",DomainRoute.Proxy)); Equal(DomainRoute.Direct,s.MatchHost("gosuslugi.ru")); True(s.DirectRules is not List<DomainRule>); True(catalog.Services is not List<RoutingService>); });
Check("preferences copy preserves independence",()=>{var p=new RuRoutingPreferences {DisabledServiceIds=new(){"gosuslugi"},CustomRules=new(){new(DomainMatch.Exact,"example.com",DomainRoute.Direct)}}; var c=p.Copy(); c.DisabledServiceIds.Clear(); c.CustomRules.Clear(); Equal(1,p.DisabledServiceIds.Count); Equal(1,p.CustomRules.Count); });
Check("preferences validate broad/invalid enum and duplicate rules",()=>{True(new RuRoutingPreferences {CustomRules=new(){new(DomainMatch.Suffix,"ru",DomainRoute.Direct)}}.Validate()!=null); True(new RuRoutingPreferences {CustomRules=new(){new((DomainMatch)90,"example.com",DomainRoute.Direct)}}.Validate()!=null); True(new RuRoutingPreferences {CustomRules=new(){new(DomainMatch.Exact,"example.com",DomainRoute.Direct),new(DomainMatch.Exact,"example.com",DomainRoute.Proxy)}}.Validate()!=null); });
Check("malformed catalog falls closed including custom direct",()=>{var broken=RoutingCatalog.Load("{ broken", "{}"); True(!broken.IsValid); True(!string.IsNullOrWhiteSpace(broken.Warning)); var s=RoutingPolicySnapshot.Create(RoutingMode.RuMode,new(){CustomRules=new(){new(DomainMatch.Suffix,"example.com",DomainRoute.Direct)}},broken); Equal(0,s.DirectRules.Count); Equal(DomainRoute.Proxy,s.MatchHost("example.com")); });
Check("catalog validates routes, schema, domains, duplicates",()=> {foreach(var fragment in new[]{"\"schemaVersion\":2","\"route\":\"proxy\"","\"value\":\"ru\"","\"match\":\"domain_keyword\""}) {var json=MiniCatalog(); var key=fragment.Split(':')[0]; var original=key switch {"\"schemaVersion\""=>"\"schemaVersion\":1","\"route\""=>"\"route\":\"direct\"","\"value\""=>"\"value\":\"example.com\"",_=>"\"match\":\"domain_suffix\""}; True(!RoutingCatalog.Load(json.Replace(original,fragment),MiniCatalog(true)).IsValid); }});
Check("shared service domain survives disabling one contribution",()=>{var json=MiniCatalog().Replace("\"services\":[", "\"services\":["+MiniService("shared")+","); var c=RoutingCatalog.Load(json,MiniCatalog(true)); True(c.IsValid); var s=RoutingPolicySnapshot.Create(RoutingMode.RuMode,new(){DisabledServiceIds=new(){"sample"}},c); Equal(DomainRoute.Direct,s.MatchHost("example.com")); });
foreach(var invalid in new[]{"\"unknown\"","42","null","false","{}","[]","\"FullVPN\""}) Check("mode invalid safe fallback "+invalid,()=>{var p=JsonSerializer.Deserialize<Envelope>("{\"Mode\":"+invalid+",\"Server\":\"keep\",\"Enabled\":true}")!; Equal(RoutingMode.FullVpn,p.Mode); Equal("keep",p.Server); True(p.Enabled); });
Check("mode valid JSON string roundtrip",()=>{var p=JsonSerializer.Deserialize<Envelope>("{\"Mode\":\"RuMode\",\"Server\":\"keep\"}")!; Equal(RoutingMode.RuMode,p.Mode); True(JsonSerializer.Serialize(p).Contains("\"Mode\":\"RuMode\"")); });
Check("missing mode defaults full VPN",()=>Equal(RoutingMode.FullVpn,JsonSerializer.Deserialize<Envelope>("{\"Server\":\"keep\"}")!.Mode));
Check("invalid null preference lists cannot expand direct",()=>{foreach(var p in new[]{new RuRoutingPreferences {DisabledServiceIds=null!},new RuRoutingPreferences {CustomRules=null!}}) {var rejected=false; try { RoutingPolicySnapshot.Create(RoutingMode.RuMode,p); } catch(ArgumentException) { rejected=true; } True(rejected);}});
Check("missing entire RU preferences cannot default direct",()=>{var rejected=false;try { RoutingPolicySnapshot.Create(RoutingMode.RuMode,null); }catch(ArgumentException) {rejected=true;} True(rejected); Equal(0,RoutingPolicySnapshot.Create(RoutingMode.FullVpn,null).DirectRules.Count);});
Check("missing persisted rule match or route is invalid",()=>{foreach(var ruleJson in new[]{"{\"Match\":1,\"Value\":\"example.com\"}","{\"Value\":\"example.com\",\"Route\":1}"}) {var rule=JsonSerializer.Deserialize<DomainRule>(ruleJson)!; True(new RuRoutingPreferences {CustomRules=new(){rule}}.Validate()!=null);}});
foreach(var shape in new[]{"\"bad\"","42","null","[]","{}","{\"DisabledServiceIds\":null,\"CustomRules\":[]}","{\"DisabledServiceIds\":[],\"CustomRules\":[\"bad\"]}","{\"DisabledServiceIds\":[42],\"CustomRules\":[]}"}) Check("malformed preferences preserve unrelated settings "+shape,()=>{var p=JsonSerializer.Deserialize<PreferenceEnvelope>("{\"RuMode\":"+shape+",\"Mtu\":1400,\"ChatName\":\"keep\"}")!; Equal(1400,p.Mtu); Equal("keep",p.ChatName); True(p.RuMode==null||p.RuMode.Validate()!=null);});
Check("valid preferences JSON roundtrip",()=>{var p=new RuRoutingPreferences {DisabledServiceIds=new(){"gosuslugi"},CustomRules=new(){new(DomainMatch.Exact,"example.com",DomainRoute.Proxy)}};var c=JsonSerializer.Deserialize<RuRoutingPreferences>(JsonSerializer.Serialize(p))!; Equal("gosuslugi",c.DisabledServiceIds.Single()); Equal(DomainRoute.Proxy,c.CustomRules.Single().Route); Equal<string?>(null,c.Validate());});
Console.WriteLine($"{checks-failures}/{checks} checks passed"); return failures==0?0:1;
static string MiniService(string id,bool proxy=false)=>"{\"id\":\""+id+"\",\"name\":\"Sample\",\"aliases\":[\"Sample\"],\"category\":\"test\",\"enabledInRuPreset\":true,\"route\":\""+(proxy?"proxy":"direct")+"\",\"endToEndVerified\":false,\"rules\":[{\"match\":\"domain_suffix\",\"value\":\""+(proxy?"youtube.com":"example.com")+"\",\"evidence\":\"test\",\"sources\":[{}]}]}";
static string MiniCatalog(bool proxy=false)=>"{\"schemaVersion\":1,\"catalogVersion\":\"test\",\"coverage\":\"seed-not-exhaustive\",\"services\":["+MiniService("sample",proxy)+"]}";
public sealed class Envelope {public RoutingMode Mode {get;set;} public string Server {get;set;}=""; public bool Enabled {get;set;} }

public sealed class PreferenceEnvelope {public RuRoutingPreferences? RuMode {get;set;}=new();public int Mtu {get;set;} public string ChatName {get;set;}="";}
